from gtlib import *
OV=L('/ganesha/temples/ashtavinayaka/','the Aṣṭavināyaka overview')
GP=L('/ganesha/foundations/ganapatya/','the Gāṇapatya tradition')
YA=L('/ganesha/forms/yuga-avatars/','the four yuga avatāras')
SRC=lambda t:[('Temple facts:',f'Wikipedia, “{t}” and “Ashtavinayaka”, as summarised in our earlier guide; temple trust information.')]
W=[('🛕','Svayambhū','Self-manifested: an image held to have appeared by itself.'),('🟠','Sindūr','The orange-red paste that coats many Gaṇeśa images.'),('🪔','Dīpamāḷā','A lamp tower of stone, lit with many lamps at festivals.'),('🌿','Dūrvā','The three-bladed grass dear to Gaṇeśa.'),('🙏','Āratī','Waving of lamps, with the song “Sukhakartā Duḥkhahartā”.'),('🌗','Caturthī · Saṅkaṣṭī','The bright and dark fourth days, sacred to Gaṇeśa.')]
# ---------- MORGAON ----------
temple(1,dict(kicker='AṢṬAVINĀYAKA 1 OF 8 · THE PEACOCK · FIRST AND LAST',
cov=covart('A walled temple with four gates and lamp towers, Gaṇeśa riding a peacock above it',g(220,170,1.3,palace())+g(110,180,.9,lamp())+g(330,180,.9,lamp())+g(220,80,.8,bird('#2a6ab8'))+g(220,70,.4,ganesha())),
cap='Lord of the peacock',how='The <b>village of peacocks</b>, the image, the legend of <b>Sindhu</b>, the walled temple with <b>four gates</b>, Moraya Gosāvī, the Peshwas, and the festivals.',
desc='Morgaon’s Mayūreśvara explained: first and last of the Aṣṭavināyaka, the peacock-riding Gaṇeśa who slew Sindhu, the north-facing image, the walled temple with four gates, Moraya Gosāvī, the Peshwas and the festivals.',
fw=['<b>Morgaon</b>, a village on the Karhā river south-east of Pune, is where the Aṣṭavināyaka begins and ends. Here Gaṇeśa is <b>Mayūreśvara</b>, Moreśvar in Marathi, lord of the peacock, who rode a peacock to defeat the demon Sindhu.','The Gāṇapatyas call it Gaṇeśa’s foremost seat on earth. This guide covers the place, the legend, the image, the fortress-like temple with its four gates, the saint Moraya Gosāvī, the Peshwas and the festivals. Start with '+OV+' for the whole circuit.'],fwtk=[('z','Why start here?'),('b','Morgaon is first and last, Zappy. The circle begins and closes with the peacock-rider.')],
glance=[('Where','Morgaon, Baramati taluka, Pune district, on the Karhā river'),('Distance','About 55 km from Pune'),('Form','Mayūreśvara (Moreśvar), seated, facing north'),('Trunk','Turned to the left'),('Legend','Gaṇeśa on a peacock slays the demon Sindhu'),('Place in circuit','First and last'),('Temple','Walled, with four gates and two lamp towers'),('Run by','Chinchwad Devasthān Trust')],
where=['<b>The village.</b> Morgaon lies about 55 km south-east of Pune in Baramati taluka, on the small river Karhā. “Mor” is Marathi for peacock: a village of peacocks.','<b>Scripture.</b> Both great Gāṇapatya texts praise it. The Mudgala Purāṇa gives it 22 chapters, and the Gaṇeśa Purāṇa counts it among Gaṇeśa’s three holiest places.','<b>First and last.</b> Pilgrims begin the Aṣṭavināyaka here and return here at the end. Many say a pilgrimage that does not close at Morgaon is not complete.'],wtk=[('z','Are there really peacocks?'),('b','You may well see some on the fields, Zappy. The name keeps the bird alive.')],wk='The <b>village of peacocks</b>.',
lt='THE LEGEND OF SINDHU',ls='Gaṇeśa on a peacock',strip=strip('Three panels: a demon swallowing a bowl of nectar; Gaṇeśa riding a peacock into battle; the demon cut open and nectar flowing out',[panel([(demon('#5a3a6a'),1),(pot('#e0a800'),.6)],'#e9e3f5',150),panel([(bird('#2a6ab8'),1.2),(ganesha(),.5)],'#dfe9f6',150),panel([(demon('#5a3a6a'),.8),(splash('#ffd60a'),.8)],'#fff3cf',150)],['the nectar thief','the peacock rider','the nectar freed']),lsrc='Gaṇeśa Purāṇa (Krīḍā Khaṇḍa) and temple tradition; tellings differ.',
lsteps=['The demon <b>Sindhu</b> swallowed a bowl of <b>amṛta</b>, the nectar of immortality, and became impossible to kill. He oppressed the gods.','In the Tretā age Gaṇeśa was born to Pārvatī after her penance at '+L('/ganesha/temples/lenyadri/','Leṇyādri')+' and grew up there.','To fight Sindhu he rode a <b>peacock</b>, a gift in the stories from his brother Skanda’s side, and so was called <b>Mayūreśvara</b>.','At Morgaon he cut the demon open and let the nectar flow out. Sindhu, without his nectar, fell.','Brahmā is said to have built the first shrine, and the Karhā river to have flowed from water spilled from his pot. Read '+YA+'.'],ltk=[('z','Gaṇeśa on a peacock, not a mouse?'),('b','In this age, Zappy. Each yuga gives him a different mount.')],lk='The peacock <b>rider</b>.',
more=[('image','THE IMAGE','Mayūreśvara facing north',gimg('A seated Gaṇeśa image with a cobra hood above and two consorts','facing north · cobra hood'),['<b>Posture.</b> Seated, facing <b>north</b>, with four arms, three eyes and the trunk turned to the left.','<b>Jewels.</b> Diamonds are set in the eyes and the navel; a cobra’s hood rises above the head. Siddhi and Buddhi stand on either side.','<b>Sindūr.</b> Believed svayambhū, the image is thickly coated in sindūr, which is said to fall away roughly once a century, most recently in 1882 and before that in 1788.','<b>The āratī.</b> Tradition says Samartha Rāmadāsa composed “Sukhakartā Duḥkhahartā” after seeing this image.'],[('z','The coating falls off by itself?'),('b','So the records say, Zappy. Once in a hundred years.')],'Jewelled eyes, <b>a cobra’s hood</b>.'),
('temple','THE TEMPLE','A walled shrine with four gates',tscene('A temple inside high walls with minarets at the corners and two lamp towers',g(60,150,.8,lamp())+g(500,150,.8,lamp())),['<b>Walls.</b> The shrine stands inside tall stone walls with minaret-like towers at the four corners, looking almost like a fort.','<b>Four gates.</b> Each faces a direction and holds a Gaṇeśa form tied to an age and an aim of life: east, Ballāḷa and dharma; south, Vighneśa and artha; west, Cintāmaṇi and kāma; north, Mahāgaṇapati and mokṣa.','<b>Courtyard.</b> Two lamp towers, a six-foot mouse, śamī and bilva trees, and, unusually, a great <b>Nandi</b>. Legend says the Nandi was being carried to a Śiva temple and refused to go past Gaṇeśa.','<b>Many gods.</b> Smaller shrines round the courtyard hold many forms of Gaṇeśa and other deities.'],[('z','A Nandi at a Gaṇeśa temple?'),('b','He stopped and wouldn’t move, Zappy. Family loyalty.')],'Four gates, <b>four aims of life</b>.'),
('history','HISTORY','Saint and Peshwas',svg(560,160,'A saint at the temple gate and a royal figure with a gift',f'<rect width="560" height="160" fill="#fde9c8"/>'+g(150,150,1.1,sage())+g(280,140,.9,palace())+g(420,150,1.1,person('#8e1f17'))),['<b>Date.</b> Unknown. The temple is usually placed between the 14th and 17th centuries; the scholar Anne Feldhaus argues for the 17th, when Moraya Gosāvī made it famous.','<b>Moraya Gosāvī.</b> The Gāṇapatya saint worshipped here before settling at Chinchwad, and walked back to Morgaon regularly. Read '+GP+'.','<b>The Peshwas.</b> In the 18th century they gave land, cash and buildings; Moraya’s descendants, the Devs of Chinchwad, long managed the temple.','<b>Today.</b> The Chinchwad Devasthān Trust administers it.'],[('z','So Morgaon made Moraya famous, or Moraya made Morgaon?'),('b','Both, Zappy. Saint and shrine grew together.')],'Saint first, <b>kings after</b>.'),
('festivals','FESTIVALS','The year at Morgaon',svg(560,160,'A palanquin procession with lamps and drums',f'<rect width="560" height="160" fill="#fff3cf"/>'+g(280,140,1.3,palace())+''.join(g(x,150,.6,person('#c0392b')) for x in (100,140,180,380,420,460))+g(280,60,.6,flag())),['<b>Gaṇeśa Caturthī</b> in Bhādrapada and <b>Māghī Gaṇeśa Jayantī</b> are the great festivals. The palanquin of Moraya Gosāvī comes from Chinchwad for the Bhādrapada festival.','<b>Saṅkaṣṭī and Aṅgārakī</b> bring crowds of devotees who fast until moonrise. Read our '+L('/ganesha/festivals/sankashti-chaturthi/overview/','Saṅkaṣṭī')+' series.','<b>Vijayadaśamī</b> and the lamp-lit nights of Kārtika are also kept.','<b>Visiting.</b> Timings and rules are set by the temple trust; check before you go.'],[('z','The palanquin walks all the way from Chinchwad?'),('b','Carried by devotees, Zappy. The saint visits his lord every year.')],'The saint <b>comes home</b>.'),
('meaning','WHY THE PEACOCK?','Pride carried and tamed',svg(560,150,'A peacock with spread tail and Gaṇeśa calm above it',f'<rect width="560" height="150" fill="#dfe9f6"/>'+g(280,140,1.6,bird('#2a6ab8'))+g(280,70,.5,ganesha())),['<b>A proud bird.</b> The peacock is beauty and pride. Gaṇeśa rides it, calm. Many read this as pride carried, not crushed: put to work for good. (Interpretation.)','<b>Sindhu’s nectar.</b> The demon wanted immortality only for himself. Gaṇeśa lets it flow out again: what is hoarded is released.','<b>First and last.</b> Starting and ending here makes the pilgrimage a circle. Every journey begins and ends with Gaṇeśa.'],[('z','So I start my exams with Gaṇeśa too?'),('b','And end them with thanks, Zappy. That’s Morgaon in a sentence.')],'Begin and <b>end</b> here.')],
words=W,gtk=[('z','So many words!'),('b','You’ll hear all of them at every Aṣṭavināyaka, Zappy.')],
end=['<b>Where.</b> Morgaon, on the Karhā, about 55 km from Pune.','<b>Form.</b> Mayūreśvara, facing north, trunk to the left.','<b>Legend.</b> Gaṇeśa on a peacock slays Sindhu.','<b>Temple.</b> Walled, four gates, two lamp towers, a Nandi.','<b>Place.</b> First and last of the eight.'],endnext='Next: '+L('/ganesha/temples/siddhatek/','Siddhaṭek')+', the right-turned trunk.',
src=SRC('Mayureshwar Temple, Morgaon'),unver='the age of the temple (dates differ); the sindūr-shedding years (temple records); the Rāmadāsa āratī story (tradition); the Nandi legend (tradition).',study='Study notes on Morgaon’s Mayūreśvara.'))
# ---------- SIDDHAṬEK ----------
temple(2,dict(kicker='AṢṬAVINĀYAKA 2 OF 8 · THE RIGHT-TURNED TRUNK · THE BHĪMĀ',
cov=covart('A hilltop temple by a wide river, devotees walking round the hill',g(220,170,1.6,mountain('#9a8a6a',False))+g(220,120,.8,palace())+'<path d="M0 190 q220 -20 440 0 v30 h-440z" fill="#8fb8de"/>'+''.join(g(x,175,.4,person('#c0392b')) for x in (120,160,280,320))),
cap='The hill of siddhi',how='The <b>hill</b> on the Bhīmā, the only <b>right-turned trunk</b> of the eight, <b>Viṣṇu’s</b> penance, Ahilyābāī’s temple and the walk <b>round the hill</b>.',
desc='Siddhaṭek’s Siddhivināyaka explained: the only Aṣṭavināyaka with a right-turned trunk, Viṣṇu’s penance before fighting Madhu and Kaiṭabha, Ahilyābāī Holkar’s temple, Haripant Phaḍke’s vow, and the walk round the hill.',
fw=['On a small hill on the north bank of the Bhīmā, in Karjat taluka of Ahilyanagar district, stands <b>Siddhivināyaka</b>, the Gaṇeśa who gives <b>siddhi</b>, success. He is the only image of the eight whose trunk turns to the right.','Here, the story says, even Viṣṇu had to stop and worship Gaṇeśa before he could win his battle. This guide covers the place, the legend, the image, Ahilyābāī Holkar’s temple, a commander’s vow and the walk round the hill. See '+OV+'.'],fwtk=[('z','Why does the trunk matter?'),('b','Right-turned images are believed powerful but hard to please, Zappy. Devotees come with extra care.')],
glance=[('Where','Siddhaṭek, Karjat taluka, Ahilyanagar district'),('River','North bank of the Bhīmā'),('Form','Siddhivināyaka, seated cross-legged'),('Trunk','Turned to the right: unique among the eight'),('Legend','Viṣṇu gains siddhi to defeat Madhu and Kaiṭabha'),('Built','Present temple by Ahilyābāī Holkar, late 18th century'),('Custom','Walking seven times round the hill'),('Run by','Chinchwad Devasthān Trust')],
where=['<b>The hill.</b> The temple stands on a low hillock about a kilometre from the village, above the Bhīmā river.','<b>Across the river.</b> It is reached from Shirapur on the southern bank, by bridge or boat; the nearest railway station is Daund.','<b>The district.</b> It is the only one of the eight in Ahilyanagar district; the others lie in Pune and Raigad.'],wtk=[('z','I cross a river to reach Gaṇeśa?'),('b','Pilgrims always did, Zappy. The crossing is part of the visit.')],wk='A hill <b>on the Bhīmā</b>.',
lt='VIṢṆU FORGETS GAṆEŚA',ls='The hill of siddhi',strip=strip('Three panels: two demons rising from sleeping Viṣṇu; Viṣṇu fighting and tiring; Viṣṇu in penance before Gaṇeśa on a hill',[panel([(vishnu(),.9),(demon(),.6),(demon('#5a3a6a'),.6)],'#dfe9f6',150),panel([(vishnu(),.8),(demon(),.8)],'#fde4e4',150),panel([(mountain('#9a8a6a',False),.7),(vishnu(),.6),(ganesha(),.4)],'#fff3cf',150)],['Madhu and Kaiṭabha','the losing fight','penance on the hill']),lsrc='Mudgala Purāṇa and temple tradition.',
lsteps=['From the ear-wax of the sleeping Viṣṇu sprang two demons, <b>Madhu</b> and <b>Kaiṭabha</b>, who attacked Brahmā as he began creation.','Viṣṇu woke and fought them, but however long he fought, he could not win.','Śiva told him the reason: he had begun without invoking <b>Gaṇeśa</b>.','Viṣṇu came to this hill, did penance and received <b>siddhi</b> from Gaṇeśa. Then he killed the demons. So the hill is Siddhaṭek, “the hill of siddhi”.','The Devī Māhātmya tells the same battle with the Goddess as the power that wakes Viṣṇu; read our '+L('/devi/devi-mahatmya/','Devī Māhātmya')+' series.'],ltk=[('z','Even Viṣṇu forgot Gaṇeśa?'),('b','In the Mudgala Purāṇa’s story, Zappy. That’s the point: everyone begins with him.')],lk='Even Viṣṇu <b>begins with Gaṇeśa</b>.',
more=[('image','THE IMAGE','Siddhivināyaka',gimg('A seated Gaṇeśa with trunk turned to the right, sheathed in brass','trunk turned right',flip=True),['<b>The trunk.</b> It turns to the <b>right</b>, rare among Gaṇeśa images and unique among the eight. Right-turned forms are believed powerful but demanding.','<b>The stone.</b> A svayambhū image sheathed in brass, seated cross-legged; his consort Siddhi sits beside him, often hidden by garlands and sindūr.','<b>Neighbours.</b> The sanctum also holds a Śiva pañcāyatana and a shrine to the goddess Śivāī.','<b>Saints.</b> Moraya Gosāvī and his son Nārāyaṇa Mahārāj are also said to have won siddhi here.'],[('z','Hard to please?'),('b','That’s the belief, Zappy. Strict worship, extra devotion.')],'The <b>right-turned</b> trunk.'),
('history','THE QUEEN AND THE COMMANDER','Ahilyābāī Holkar and Haripant Phaḍke',svg(560,160,'A queen offering a temple model and a commander walking round a temple',f'<rect width="560" height="160" fill="#fde9c8"/>'+g(140,150,1.1,person('#8e1f17'))+g(280,140,1,palace())+g(420,150,1.1,person('#1d4f8a'))),['<b>The first temple.</b> Tradition says Viṣṇu built it; it was later destroyed, and a cowherd found the image again after a vision.','<b>Ahilyābāī Holkar.</b> The great queen of Indore, who rebuilt temples from Kāśī to Somnāth, built the present temple in the late 18th century.','<b>Haripant Phaḍke.</b> A Peshwa commander who had lost his post vowed 21 circuits of the temple a day for 21 days; he regained his command, it is said, and built the drum-house and the stone path.','<b>The hall.</b> The outer hall was rebuilt in 1970.'],[('z','Who was Ahilyābāī?'),('b','The queen of Indore, Zappy, who rebuilt temples all over India. Siddhaṭek is one of hers.')],'A queen’s <b>gift</b>.'),
('hillwalk','ROUND THE HILL','Pradakṣiṇā of the hillock',svg(560,160,'Pilgrims walking a path round a scrubby hill',f'<rect width="560" height="160" fill="#e3f5e9"/>'+g(280,150,1.8,mountain('#9a8a6a',False))+'<ellipse cx="280" cy="120" rx="200" ry="30" fill="none" stroke="#b08a5a" stroke-width="5" stroke-dasharray="10 8"/>'+''.join(g(x,140,.5,person('#c0392b')) for x in (110,200,380,460))),['<b>The custom.</b> Devotees walk seven times round the hillock on which the temple stands.','<b>The path.</b> It is unpaved and runs through thorny scrub. The effort is part of the offering.','<b>The meaning.</b> Pradakṣiṇā keeps the god on your right, at the centre of your path. Seven rounds echo the seven steps of a vow. (Interpretation.)'],[('z','Seven times round a hill?'),('b','Through thorns, Zappy. Devotees say the effort is the offering.')],'Seven rounds <b>through the thorns</b>.'),
('festivals','FESTIVALS AND VISITING','When to go',svg(560,150,'A temple on a hill with lamps and a crowd at the river crossing',f'<rect width="560" height="150" fill="#fff3cf"/>'+g(280,130,1,palace())+river(560,140)+''.join(g(x,140,.4,lamp()) for x in (150,200,360,410))),['<b>Festivals.</b> Bhādrapada Gaṇeśa Caturthī, Māghī Gaṇeśa Jayantī and the monthly Saṅkaṣṭī and Vināyakī days draw crowds.','<b>In the circuit.</b> Second after Morgaon; from here the road turns west towards the ghats and Pālī.','<b>Practical.</b> Arrangements are set by the temple trust; check locally.'],[('z','Is it crowded?'),('b','On Caturthī, very, Zappy. On a quiet weekday, peaceful.')],'Second <b>of eight</b>.'),
('meaning','WHAT SIDDHI MEANS','Success that starts right',svg(560,150,'A small figure climbing steps to a lamp at the top',f'<rect width="560" height="150" fill="#dfe9f6"/>'+''.join(f'<rect x="{120+k*50}" y="{130-k*16}" width="50" height="{20+k*16}" fill="#c9a06a"/>' for k in range(6))+g(450,40,.8,lamp())+g(170,110,.7,child())),['<b>Siddhi.</b> Accomplishment: the success of an undertaking. Gaṇeśa is Siddhidātā, the giver of siddhi.','<b>Viṣṇu’s lesson.</b> Power alone could not win; the right beginning could. Many read the story as about humility before any task. (Interpretation.)','<b>The right trunk.</b> Devotees say the right-turned form asks for steadiness and care in worship: success that must be earned.'],[('z','So I invoke Gaṇeśa, then I study?'),('b','Both, Zappy. Viṣṇu still had to fight.')],'Begin right, <b>then work</b>.')],
words=W,gtk=[('z','More words?'),('b','The same ones you’ll meet at each of the eight, Zappy.')],
end=['<b>Where.</b> A hill on the Bhīmā, Ahilyanagar district.','<b>Form.</b> Siddhivināyaka, trunk to the right.','<b>Legend.</b> Viṣṇu wins siddhi before slaying Madhu and Kaiṭabha.','<b>Temple.</b> Built by Ahilyābāī Holkar; Haripant Phaḍke’s vow.','<b>Custom.</b> Seven rounds of the hill.'],endnext='Next: '+L('/ganesha/temples/pali/','Pālī')+', the god with a child’s name.',
src=SRC('Siddhivinayak Temple, Siddhatek'),unver='the dates of the temple and hall; the Haripant Phaḍke story (tradition); the cowherd’s rediscovery (tradition).',study='Study notes on Siddhaṭek’s Siddhivināyaka.'))
# ---------- PĀLĪ ----------
temple(3,dict(kicker='AṢṬAVINĀYAKA 3 OF 8 · THE CHILD DEVOTEE · THE ŚRĪ-SHAPED TEMPLE',
cov=covart('A boy tied to a tree, a Brahmin freeing him, and a stone temple below a mountain',g(330,170,1.5,mountain('#6a8a5a',False))+g(100,180,1.2,tree('#2f6a3a'))+g(110,180,.7,child())+g(180,180,.9,sage('#fff'))+g(300,190,.8,palace())),
cap='Ballāḷa’s lord',how='The boy <b>Ballāḷa</b>, the thrown stone <b>Ḍhuṇḍhi</b>, the image dressed as a <b>Brahmin</b>, the temple shaped like <b>Śrī</b>, and the <b>Portuguese bell</b>.',
desc='Pālī’s Ballāḷeśvara explained: the only Aṣṭavināyaka named after a devotee, the story of the boy Ballāḷa, Ḍhuṇḍhi Vināyaka, the image dressed as a Brahmin, the temple shaped like the letter Śrī, and the bell from Vasai.',
fw=['Below the cliffs of Sarasgaḍ fort, by the Ambā river in Raigad district, stands the only Gaṇeśa in India named after a child devotee: <b>Ballāḷeśvara</b>, “Ballāḷa’s lord”.','A boy who loved Gaṇeśa was beaten and tied to a tree by his own father. Gaṇeśa came, freed him, and stayed for ever under his name. This guide covers the story, the stone that was thrown away, the image, the temple shaped like a letter, and a bell captured in war. See '+OV+'.'],fwtk=[('z','A god named after a child?'),('b','The only one of the eight, Zappy. Gaṇeśa took the boy’s side.')],
glance=[('Where','Pālī, Sudhagad taluka, Raigad district'),('Route','About 111 km from Pune via Lonavla and Khopoli'),('Form','Ballāḷeśvara, facing east, trunk to the left'),('Legend','The boy Ballāḷa freed by Gaṇeśa'),('First visit','Ḍhuṇḍhi Vināyaka, facing west, behind the temple'),('Temple','Stone, plan shaped like the letter Śrī; rebuilt 1760'),('Bell','From the Portuguese, after Vasai, 1739'),('Prasāda','Besan laḍḍu, not modaka')],
where=['<b>Konkan.</b> Pālī lies below the Sahyādri in Raigad district, between the fort of Sarasgaḍ and the Ambā river.','<b>The road.</b> From Pune it is about 111 km, down the ghats by Lonavla and Khopoli.','<b>The mountain.</b> The image is said to echo the shape of the mountain behind the temple.'],wtk=[('z','Down the ghats?'),('b','Pālī and Mahaḍ are the two coastal-side temples, Zappy. The air changes.')],wk='Below the <b>fort</b>.',
lt='BALLĀḶA AND HIS FATHER',ls='The boy Gaṇeśa would not abandon',strip=strip('Three panels: children worshipping a stone in the forest; an angry father tying a boy to a tree; a Brahmin freeing the boy',[panel([(child(),.8),(child(),.7),(ganesha(),.4)],'#e3f5e9',150),panel([(tree('#2f6a3a'),.8),(child(),.6),(person('#8e1f17'),.8)],'#fde4e4',150),panel([(sage('#fff'),.9),(child(),.7)],'#fff3cf',150)],['play-worship','the angry father','the Brahmin']),lsrc='Gaṇeśa Purāṇa (Upāsanā Khaṇḍa) and temple tradition.',
lsteps=['In Pallīpur, old Pālī, lived the merchant <b>Kalyāṇ Śeṭh</b> and his wife Indumatī. Their son <b>Ballāḷa</b> loved Gaṇeśa more than anything.','He and his friends played at worship in the forest, with a stone as Gaṇeśa, and stayed out for hours. The other parents blamed Ballāḷa.','His father, furious, broke up the worship, <b>threw away the stone</b>, beat the boy and tied him to a tree.','Ballāḷa kept calling on Gaṇeśa. Gaṇeśa came as a <b>Brahmin</b>, freed him and healed his wounds.','The boy asked one boon: “Stay here for ever.” Gaṇeśa agreed, and took the boy’s name: <b>Ballāḷeśvara</b>.'],ltk=[('z','His own father?'),('b','In the story, Zappy. And Gaṇeśa chose the child. That’s why the god has his name.')],lk='The god with <b>a child’s name</b>.',
more=[('dhundhi','ḌHUṆḌHI VINĀYAKA','The thrown stone',svg(560,160,'A small west-facing shrine with a rough stone image',f'<rect width="560" height="160" fill="#fde9c8"/>'+g(280,150,1,palace())+'<ellipse cx="280" cy="120" rx="18" ry="22" fill="#d35400"/>'+g(450,150,1,lamp())),['<b>The stone.</b> The stone Kalyāṇ threw away is worshipped as <b>Ḍhuṇḍhi Vināyaka</b>, in a shrine behind the main temple.','<b>Facing west.</b> Rare for a Gaṇeśa; it is also held to be svayambhū.','<b>First.</b> By custom pilgrims greet Ḍhuṇḍhi Vināyaka before Ballāḷeśvara. He has his own five-day festival.'],[('z','The thrown stone is worshipped first?'),('b','Thrown away by anger, honoured first ever since, Zappy.')],'The <b>rejected</b> stone, honoured first.'),
('image','THE IMAGE','Ballāḷeśvara dressed as a Brahmin',gimg('A Gaṇeśa image with jewelled eyes, dressed as a Brahmin, with a mouse holding a modaka','facing east'),['<b>Form.</b> Facing east, trunk to the left, with diamonds in the eyes and navel and a mouse in front holding a modaka.','<b>Dress.</b> The image is dressed as a Brahmin, the form in which Gaṇeśa came to free Ballāḷa.','<b>Prasāda.</b> Unusually, it is <b>besan laḍḍu</b> rather than modaka.'],[('z','Why diamonds in the eyes?'),('b','They catch the lamplight, Zappy. Many Aṣṭavināyaka images have them.')],'Dressed as <b>a Brahmin</b>.'),
('temple','THE TEMPLE OF ŚRĪ','A plan shaped like a letter',svg(560,160,'A temple plan drawn in the shape of a curving letter, with the rising sun',f'<rect width="560" height="160" fill="#fff3cf"/><path d="M200 120 q40 -80 80 -40 q40 40 80 -20" fill="none" stroke="#8e1f17" stroke-width="10"/>'+g(460,50,1,sun())+g(120,140,.8,palace())),['<b>Rebuilt.</b> The old wooden temple was rebuilt in stone in 1760 under the Phaḍnavīs family, with lead mixed into the mortar, by one account.','<b>Śrī.</b> Its plan is shaped like the Devanāgarī letter Śrī, the syllable of auspiciousness.','<b>The sun.</b> The temple faces east; after the winter solstice the rising sun falls on the image.','<b>Water.</b> Two lakes adjoin it, one kept for the deity’s worship.'],[('z','A temple shaped like a letter?'),('b','Śrī, Zappy. You’d see it best from the sky.')],'A temple <b>shaped like Śrī</b>.'),
('bell','THE BELL FROM VASAI','A trophy of war',svg(560,150,'A great church-style bell hanging in a temple',f'<rect width="560" height="150" fill="#fde9c8"/>'+g(280,110,2.2,bell())+g(110,140,.8,palace())),['<b>1739.</b> Chimājī Appā, brother of Peshwa Bājīrāo I, captured Vasai (Bassein) from the Portuguese.','<b>The bells.</b> Bells from the Portuguese churches were brought back and offered at Aṣṭavināyaka and other temples. Pālī’s hangs here still.','<b>A word.</b> The bell is a war trophy; today it simply calls devotees to āratī.'],[('z','A church bell in a Gaṇeśa temple?'),('b','History hangs there, Zappy. Now it just rings for āratī.')],'A <b>bell</b> with a history.'),
('meaning','THE CHILD’S FAITH','What Pālī teaches',svg(560,150,'A child with folded hands before a small Gaṇeśa stone',f'<rect width="560" height="150" fill="#e3f5e9"/>'+g(240,140,1.2,child())+'<ellipse cx="340" cy="120" rx="18" ry="22" fill="#d35400"/>'+g(450,140,1,lamp())),['<b>Play is worship.</b> Ballāḷa worshipped a stone in play, and Gaṇeśa accepted it. Many read this as: sincerity matters more than ceremony. (Interpretation.)','<b>The weak protected.</b> The god came to the bound child, not to the powerful father.','<b>The rejected honoured.</b> The thrown stone is greeted first. What was cast away is made precious.'],[('z','So my play-pūjā counts?'),('b','If your heart is in it, Zappy. Ask Ballāḷa.')],'<b>Sincerity</b> first.')],
words=W,gtk=[('z','Do I know these now?'),('b','You’ll use them at Mahaḍ next, Zappy.')],
end=['<b>Where.</b> Pālī, Raigad, below Sarasgaḍ.','<b>Form.</b> Ballāḷeśvara, dressed as a Brahmin.','<b>Legend.</b> The boy Ballāḷa freed; the god takes his name.','<b>Customs.</b> Ḍhuṇḍhi Vināyaka first; besan laḍḍu.','<b>Temple.</b> Shaped like Śrī; the Vasai bell.'],endnext='Next: '+L('/ganesha/temples/mahad/','Mahaḍ')+', the boon-giver by the pond.',
src=SRC('Ballaleshwar Temple, Pali'),unver='the 1640 and 1760 building dates and the lead mortar (accounts differ); the bell’s exact origin (tradition).',study='Study notes on Pālī’s Ballāḷeśvara.'))
# ---------- MAHAḌ ----------
temple(4,dict(kicker='AṢṬAVINĀYAKA 4 OF 8 · THE BOON-GIVER · THE LAMP SINCE 1892',
cov=covart('A simple tiled temple beside a pond, with a lamp burning inside',g(220,170,1.3,palace())+'<ellipse cx="90" cy="190" rx="70" ry="14" fill="#8fb8de"/>'+g(360,180,1.1,lamp())+g(220,130,.4,ganesha())),
cap='The boon-giver by the pond',how='The sage <b>Gṛtsamada</b>, the image <b>found in a pond</b>, the simple temple, the lamp burning since <b>1892</b>, and the one shrine where you may come <b>close</b>.',
desc='Mahaḍ’s Varadavināyaka explained: the sage Gṛtsamada, the image found in the lake in 1690, the simple temple of 1725, the lamp burning since 1892, and the only Aṣṭavināyaka where devotees may approach the image closely.',
fw=['In the village of Mahaḍ (Maḍh), near Khopoli in Raigad district, stands the most homely of the eight: <b>Varadavināyaka</b>, “the boon-giving Vināyaka”, in a simple tiled temple beside a pond.','Its story is of a sage, Gṛtsamada, whose name stands at the head of the Ṛgveda verse every Gaṇeśa worship begins with. This guide covers the legend, the image found in the pond, the temple, the lamp that has burned since 1892, and why devotees here may come close to Gaṇeśa. See '+OV+'.'],fwtk=[('z','Is this the Mahāḍ by the sea?'),('b','No, Zappy, a different place: Mahaḍ near Khopoli. Easy to mix up.')],
glance=[('Where','Mahaḍ (Maḍh), Khalapur taluka, Raigad district, near Khopoli'),('Note','Not the coastal town of Mahāḍ in south Raigad'),('Form','Varadavināyaka, facing east, trunk to the left'),('Found','In the adjoining lake in 1690'),('Built','1725, by Subhedār Rāmjī Mahādev Biwalkar'),('Lamp','A nandādīp burning since 1892'),('Unique','Devotees may approach the image closely'),('Sage','Gṛtsamada, seer of the Ṛgveda’s second book')],
where=['<b>Near Khopoli.</b> Mahaḍ lies in Khalapur taluka, just off the Mumbai–Pune road, below the ghats.','<b>Not Mahāḍ.</b> The better-known coastal town of Mahāḍ is far to the south; the temple village is often spelt Maḍh to avoid confusion.','<b>Old name.</b> Tradition calls the forest here Bhadraka, or Puṣpaka.'],wtk=[('z','Close to the highway?'),('b','A short turn off it, Zappy. Many stop on the way to Pune.')],wk='Below the <b>ghats</b>.',
lt='THE SAGE GṚTSAMADA',ls='A curse, and a boon',strip=strip('Three panels: a sage and his mother arguing; the sage in penance in a forest; Gaṇeśa appearing to bless him',[panel([(sage(),.9),(devi(sari='#c0392b',items=()),.8)],'#fde4e4',150),panel([(tree('#2f6a3a'),.8),(sage(),.8)],'#e3f5e9',150),panel([(sage(),.7),(ganesha(),.6)],'#fff3cf',150)],['mother and son','the forest penance','the boon-giver']),lsrc='Temple tradition and the Gaṇeśa Purāṇa; tellings differ.',
lsteps=['<b>Gṛtsamada</b> was a learned sage, but a painful story about his birth troubled him and his mother.','Hurt and angry, mother and son cursed each other.','Gṛtsamada went into the forest of Bhadraka and did long penance to Gaṇeśa.','Gaṇeśa appeared, blessed him and the place, and agreed to stay as <b>Varadavināyaka</b>, the boon-giver.','Tradition names Gṛtsamada as the seer of the Ṛgveda’s second book, which holds the verse “<i>gaṇānāṃ tvā gaṇapatiṃ havāmahe</i>”. Read '+L('/ganesha/hymns/ganapati-rigveda/','Gaṇapati in the Ṛgveda')+'.'],ltk=[('z','The man who wrote “gaṇānāṃ tvā”?'),('b','So tradition says, Zappy. The oldest Gaṇapati verse, linked to this forest.')],lk='The seer of <b>gaṇānāṃ tvā</b>.',
more=[('image','THE IMAGE FROM THE POND','Found in 1690',svg(560,160,'A man lifting a Gaṇeśa image out of a pond',f'<rect width="560" height="160" fill="#dfe9f6"/><ellipse cx="280" cy="135" rx="200" ry="22" fill="#8fb8de"/>'+g(240,130,1,person('#1d4f8a'))+g(330,120,.6,ganesha())),['<b>Found.</b> The image was found submerged in the adjoining lake in 1690 by a devotee, Dhoṇḍu Pauḍkar, and kept for a time in a nearby goddess temple.','<b>Form.</b> Facing east with the trunk to the left, flanked by Riddhi and Siddhi.','<b>Old and new.</b> By one account the weathered original is shown outside the sanctum and a new image installed.','<b>Honest note.</b> An image found in a lake sits uneasily with the svayambhū claim, as scholars note.'],[('z','Found in a pond?'),('b','So the story goes, Zappy. A dream, a dive and a god.')],'Out of <b>the pond</b>.'),
('temple','THE SIMPLE TEMPLE','Built in 1725',tscene('A simple tiled-roof temple with four elephant figures at its sides',g(80,150,.6,elephant(False))+g(480,150,.6,elephant(False))),['<b>Built.</b> In 1725 by Rāmjī Mahādev Biwalkar, the Maratha subhedār of Kalyāṇ, who also founded the village.','<b>Plain.</b> A simple building with a tiled roof, often called a <b>maṭh</b> rather than a grand temple.','<b>Dome and guards.</b> A 25-foot dome with a golden finial and cobra designs; four elephants guard its four sides.','<b>Inside.</b> A mouse, the Navagraha and a Śiva-liṅga; a gomukh spout of holy water to the north.'],[('z','Why so plain?'),('b','Plain suits a boon-giver, Zappy. You come as you are.')],'Plain and <b>near</b>.'),
('lamp','THE LAMP SINCE 1892','A flame that never went out',svg(560,160,'A tall oil lamp burning steadily in a dark shrine',f'<rect width="560" height="160" fill="#2a1f2e"/>'+g(280,150,2.4,lamp())+'<circle cx="280" cy="60" r="40" fill="#ffd60a" opacity=".15"/>'),['<b>The nandādīp.</b> An oil lamp in the shrine is said to have burned without a break since 1892.','<b>Care.</b> It is kept alight by the temple, refilled through every day and night.','<b>Meaning.</b> Many see it as unbroken devotion: a flame passed from one generation of keepers to the next. (Interpretation.)'],[('z','Since 1892, really?'),('b','That’s the temple’s tradition, Zappy. Someone has been minding it all that time.')],'An <b>unbroken</b> flame.'),
('close','COME CLOSE','The one shrine you may approach',svg(560,160,'A devotee kneeling right beside a Gaṇeśa image',f'<rect width="560" height="160" fill="#fff3cf"/>'+g(320,150,1.3,ganesha())+g(200,150,1.1,namaste('#c0392b'))),['<b>Unique.</b> Mahaḍ is the only Aṣṭavināyaka where devotees may enter the sanctum and pray close to the image.','<b>Boons.</b> Many come with a particular wish: a child, a job, a healing, a peaceful home.','<b>Festivals.</b> Māghī Gaṇeśa Jayantī is the great festival here; Caturthī and Saṅkaṣṭī bring crowds. Arrangements are set by the temple trust.'],[('z','I can stand right next to Gaṇeśa?'),('b','Here you can, Zappy. Mind the queue.')],'Close <b>enough to whisper</b>.'),
('meaning','THE BOON-GIVER','What Mahaḍ teaches',svg(560,150,'Gaṇeśa with one hand raised in blessing over a small lamp',f'<rect width="560" height="150" fill="#e3f5e9"/>'+g(280,140,1.3,ganesha())+g(420,140,.9,lamp())),['<b>Vara.</b> A boon: what you ask for. Varada is the giver of boons, his hand lowered towards the devotee.','<b>From hurt to blessing.</b> Gṛtsamada came carrying a quarrel and a curse; he left with a blessing. Many read Mahaḍ as a place to bring what hurts. (Interpretation.)','<b>The Veda.</b> The sage of the oldest Gaṇapati verse links this simple shrine to the beginning of Gaṇeśa worship itself.'],[('z','So I can ask for a boon?'),('b','Ask, Zappy. And then do your part.')],'Bring <b>what hurts</b>.')],
words=W,gtk=[('z','Same words again!'),('b','The whole circuit shares them, Zappy.')],
end=['<b>Where.</b> Mahaḍ near Khopoli, Raigad.','<b>Form.</b> Varadavināyaka, found in the pond in 1690.','<b>Legend.</b> The sage Gṛtsamada’s penance.','<b>Temple.</b> Simple, 1725; the lamp since 1892.','<b>Unique.</b> You may come close.'],endnext='Next: '+L('/ganesha/temples/theur/','Theūr')+', the wish-jewel.',
src=SRC('Varadvinayak, Mahad'),unver='the 1690 finding and the 1892 lamp (temple tradition); whether the original image is the one outside (accounts differ); Gṛtsamada’s family story (tellings differ).',study='Study notes on Mahaḍ’s Varadavināyaka.'))
